package backend

const Endpoint = "GET /items"

func FetchItems(cursor string, limit int) string {
  if limit < 1 {
    return `{"items":[],"next_cursor":null}`
  }
  start := 0
  if cursor == "cursor-1" {
    start = 1
  }
  if cursor == "cursor-2" {
    start = 2
  }
  if cursor != "" && cursor != "cursor-1" && cursor != "cursor-2" {
    return `{"items":[],"next_cursor":null}`
  }
  end := start + limit
  if end > 3 {
    end = 3
  }
  items := "["
  if start == 0 {
    items += `{"id":"i1","name":"one"}`
    if end > 1 {
      items += `,{"id":"i2","name":"two"}`
    }
    if end > 2 {
      items += `,{"id":"i3","name":"three"}`
    }
  }
  if start == 1 {
    items += `{"id":"i2","name":"two"}`
    if end > 2 {
      items += `,{"id":"i3","name":"three"}`
    }
  }
  if start == 2 {
    items += `{"id":"i3","name":"three"}`
  }
  items += "]"
  nextCursor := "null"
  if end < 3 {
    if end == 1 {
      nextCursor = `"cursor-1"`
    } else {
      nextCursor = `"cursor-2"`
    }
  }
  return `{"items":` + items + `,"next_cursor":` + nextCursor + `}`
}
